import {
	SEARCH_ANIMATION_DURATION,
	SEARCH_BAR_HEIGHT,
	SEARCH_HISTORY_KEY
} from '@/constants'
import { HistoryIcon, XIcon } from 'lucide-react-native'
import Animated, {
	useAnimatedStyle,
	useDerivedValue,
	withDelay,
	withSpring,
	withTiming
} from 'react-native-reanimated'
import {
	TextInput,
	View,
	TouchableOpacity,
	Text,
	useWindowDimensions,
	Pressable,
	StyleSheet
} from 'react-native'
import { AnimatedTouchableOpacity } from '@/components'
import { colors, Theme, useTheme } from '@/theme'
import { useReanimatedKeyboardAnimation } from 'react-native-keyboard-controller'
import { defineStyles } from '@/utils/defineStyles'
import { LiquidGlassSearchBar } from './LiquidGlassSearchBar'
import { AnimatePresence, MotiTransitionProp, MotiView } from 'moti'
import React, { useEffect, useState } from 'react'
import * as Haptics from 'expo-haptics'
import { BlurView } from 'expo-blur'
import { LiquidGlassView } from '../LiquidGlassView'
import AsyncStorage from '@react-native-async-storage/async-storage'

const SEARCH_BAR_OFFSET_OPEN = 16
const SEARCH_HISTORY_DELAY = 50
const SEARCH_HISTORY_DELAY_INTERVAL = 50

const MOTI_TRANSITION_CONFIG: MotiTransitionProp = {
	type: 'timing',
	duration: 500
}

const MOTI_EXIT_TRANSITION_CONFIG: MotiTransitionProp = {
	type: 'timing',
	duration: SEARCH_ANIMATION_DURATION,
	delay: 0
}

const MOTI_FROM_CONFIG = { opacity: 0, transform: [{ translateY: 100 }] }
const MOTI_ANIMATE_CONFIG = { opacity: 1, transform: [{ translateY: 0 }] }
const MOTI_EXIT_CONFIG = { opacity: 0, transform: [{ translateY: 100 }] }

type SearchHistoryButtonProps = {
	item: string
	removeFromSearchHistory: (item: string) => void
	setSearchValue: (searchValue: string) => void
}

const SearchHistoryButton = ({
	item,
	removeFromSearchHistory,
	setSearchValue
}: SearchHistoryButtonProps) => {
	const { theme, isDark } = useTheme()

	const handlePress = () => {
		Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
		setSearchValue(item)
	}

	const handleRemove = () => {
		removeFromSearchHistory(item)
	}

	return (
		<TouchableOpacity
			style={styles.searchHistoryItems(theme, isDark)}
			onPress={handlePress}
		>
			<HistoryIcon
				size={22}
				color={isDark ? colors[theme].gray[900] : colors[theme].gray[600]}
			/>
			<Text style={styles.searchHistoryItemText(theme, isDark)}>{item}</Text>
			<TouchableOpacity onPress={handleRemove}>
				<XIcon
					size={22}
					color={isDark ? colors[theme].gray[900] : colors[theme].gray[600]}
				/>
			</TouchableOpacity>
		</TouchableOpacity>
	)
}

type SearchBarOverlayProps = {
	isSearchBarOpen: boolean
	setIsSearchBarOpen: (isSearchBarOpen: boolean) => void
	searchInputRef: React.RefObject<TextInput | null>
	searchValue: string
	setSearchValue: (searchValue: string) => void
	placeholder?: string
	storageKey?: string
}

export const SearchBarOverlay = ({
	isSearchBarOpen,
	setIsSearchBarOpen,
	searchInputRef,
	searchValue,
	setSearchValue,
	placeholder = 'Search',
	storageKey = SEARCH_HISTORY_KEY
}: SearchBarOverlayProps) => {
	const { theme } = useTheme()
	const { height: screenHeight } = useWindowDimensions()
	const { height, progress } = useReanimatedKeyboardAnimation()

	const [searchHistory, setSearchHistory] = useState<string[]>([])

	useEffect(() => {
		const fetchSearchHistory = async () => {
			const historyString = await AsyncStorage.getItem(storageKey)
			const history = historyString ? JSON.parse(historyString) : []
			setSearchHistory(Array.isArray(history) ? history : [])
		}
		fetchSearchHistory()
	}, [storageKey])

	const addToSearchHistory = (value: string) => {
		const trimmedValue = value.trim()
		if (!trimmedValue) return

		const currentHistory = Array.isArray(searchHistory) ? searchHistory : []
		let newHistory = [...currentHistory]
		const existingIndex = newHistory.indexOf(trimmedValue)
		if (existingIndex !== -1) {
			newHistory.splice(existingIndex, 1)
		}
		newHistory = [trimmedValue, ...newHistory]
		const lastThreeFromHistory = newHistory.slice(0, 3)
		AsyncStorage.setItem(storageKey, JSON.stringify(lastThreeFromHistory))
		setSearchHistory(lastThreeFromHistory)
	}

	const removeFromSearchHistory = (value: string) => {
		const currentHistory = Array.isArray(searchHistory) ? searchHistory : []
		const newHistory = currentHistory.filter((item) => item !== value)
		AsyncStorage.setItem(storageKey, JSON.stringify(newHistory))
		setSearchHistory(newHistory)
		setSearchValue('')
	}

	const motiTransitionConfigs = (() => {
		const currentHistory = Array.isArray(searchHistory) ? searchHistory : []
		return currentHistory.map((_, index) => ({
			...MOTI_TRANSITION_CONFIG,
			delay: SEARCH_HISTORY_DELAY + (3 - index) * SEARCH_HISTORY_DELAY_INTERVAL
		}))
	})()

	const animatedSearchHistoryStyle = useAnimatedStyle(() => {
		const isKeyboardAppearing = progress.get() > 0
		const delay = isKeyboardAppearing ? SEARCH_HISTORY_DELAY : 0

		return {
			bottom: withDelay(
				delay,
				withSpring(
					progress.get()
						? -height.get() + SEARCH_BAR_OFFSET_OPEN + SEARCH_BAR_HEIGHT
						: 128,
					{
						duration: SEARCH_ANIMATION_DURATION,
						dampingRatio: 1.25
					}
				)
			)
		}
	})

	const searchValueDerived = useDerivedValue(() => searchValue)

	const animatedSearchValueOpacityStyle = useAnimatedStyle(() => ({
		opacity: withTiming(searchValueDerived.get() ? 0 : 1, {
			duration: SEARCH_ANIMATION_DURATION
		})
	}))

	const animatedSearchBarStyle = useAnimatedStyle(() => {
		// guard to make sure it doesn't animate when other inputs are focused
		if (!isSearchBarOpen)
			return {
				opacity: 0,
				bottom: screenHeight - 200
			}
		return {
			opacity: withTiming(progress.get() ? 1 : 0, {
				duration: SEARCH_ANIMATION_DURATION
			}),
			bottom: withSpring(
				progress.get()
					? -height.get() + SEARCH_BAR_OFFSET_OPEN
					: screenHeight - 200,
				{
					duration: SEARCH_ANIMATION_DURATION,
					dampingRatio: 1.25
				}
			)
		}
	})

	return (
		<>
			<AnimatePresence>
				{isSearchBarOpen && !searchValue && (
					<MotiView
						from={{ opacity: 0 }}
						animate={{ opacity: 1 }}
						exit={{ opacity: 0 }}
						style={[StyleSheet.absoluteFillObject, { zIndex: 4 }]}
					>
						<BlurView
							style={StyleSheet.absoluteFillObject}
							intensity={70}
							tint="systemChromeMaterial"
							pointerEvents="none"
						/>
						<Pressable
							onPress={() => {
								setIsSearchBarOpen(false)
								searchInputRef.current?.blur()
								addToSearchHistory(searchValue)
							}}
							style={StyleSheet.absoluteFillObject}
						/>
					</MotiView>
				)}
			</AnimatePresence>
			<AnimatePresence>
				{isSearchBarOpen && (
					<Animated.View
						style={[
							styles.searchHistoryContainer,
							animatedSearchHistoryStyle,
							animatedSearchValueOpacityStyle
						]}
						pointerEvents="box-none"
					>
						{(Array.isArray(searchHistory) ? searchHistory : []).map(
							(item, index) => (
								<MotiView
									key={`${item}-${index}`}
									from={MOTI_FROM_CONFIG}
									animate={MOTI_ANIMATE_CONFIG}
									exit={MOTI_EXIT_CONFIG}
									transition={motiTransitionConfigs[index]}
									exitTransition={MOTI_EXIT_TRANSITION_CONFIG}
								>
									<SearchHistoryButton
										item={item}
										removeFromSearchHistory={removeFromSearchHistory}
										setSearchValue={setSearchValue}
									/>
								</MotiView>
							)
						)}
					</Animated.View>
				)}
			</AnimatePresence>
			<Animated.View
				style={[styles.searchBarContainerButton, animatedSearchBarStyle]}
				pointerEvents="box-none"
			>
				<View style={styles.searchBarView}>
					<AnimatedTouchableOpacity
						onPress={() => {
							Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
							if (searchInputRef?.current) {
								searchInputRef.current.focus()
							}
						}}
						activeOpacity={1}
						style={styles.liquidGlassWrapper}
					>
						<LiquidGlassSearchBar
							searchInputRef={searchInputRef}
							setIsSearchBarOpen={setIsSearchBarOpen}
							isButton={false}
							searchValue={searchValue}
							placeholder={placeholder}
							setSearchValue={setSearchValue}
							addSearchToHistory={addToSearchHistory}
						/>
					</AnimatedTouchableOpacity>
					<AnimatedTouchableOpacity
						style={styles.closeButton}
						onPress={() => {
							Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
							if (searchInputRef?.current) {
								searchInputRef.current.blur()
							}
							setSearchValue('')
						}}
					>
						<LiquidGlassView
							isInteractive={true}
							style={styles.liquidGlass}
							glassEffectStyle="regular"
						>
							<View style={styles.closeIconPosition}>
								<XIcon size={28} color={colors[theme].gray[900]} />
							</View>
						</LiquidGlassView>
					</AnimatedTouchableOpacity>
				</View>
			</Animated.View>
		</>
	)
}

const styles = defineStyles({
	searchHistoryContainer: {
		paddingLeft: 20,
		marginBottom: 16,
		position: 'absolute',
		left: 0,
		right: 0,
		zIndex: 8,
		gap: 12
	},
	searchBarContainerButton: {
		width: '100%',
		zIndex: 9,
		gap: 16,
		position: 'absolute',
		left: 0,
		right: 0
	},
	searchHistoryItems: (theme: Theme, isDark: boolean) => ({
		backgroundColor: isDark ? colors[theme].gray[75] : colors[theme].gray[50],
		alignSelf: 'flex-start',
		paddingHorizontal: 12,
		paddingVertical: 10,
		marginBottom: 6,
		flexDirection: 'row',
		alignItems: 'center',
		gap: 10,
		borderRadius: 12
	}),
	searchHistoryItemText: (theme: Theme, isDark: boolean) => ({
		color: isDark ? colors[theme].gray[900] : colors[theme].gray[600],
		fontSize: 16,
		fontWeight: '500'
	}),
	searchBarView: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		gap: 8,
		paddingHorizontal: 20
	},
	liquidGlassWrapper: {
		width: '80%',
		alignSelf: 'center'
	},
	liquidGlass: {
		borderRadius: 28,
		width: '100%',
		height: SEARCH_BAR_HEIGHT
	},
	closeButton: {
		alignItems: 'center',
		justifyContent: 'center'
	},
	closeIconPosition: {
		justifyContent: 'center',
		alignItems: 'center',
		width: SEARCH_BAR_HEIGHT,
		height: SEARCH_BAR_HEIGHT
	},
	fakeLiquidGlass: (theme: Theme, isDark: boolean) => ({
		borderRadius: 28,
		backgroundColor: isDark ? colors[theme].gray[100] : colors[theme].gray[50]
	})
})
